```rust
use std::collections::{HashMap, VecDeque};

#[derive(Clone, Debug, PartialEq, Eq)]
pub struct Message {
    pub topic: String,
    pub payload: String,
}

#[derive(Clone, Debug, PartialEq, Eq)]
pub struct Trace {
    pub thread_id: u32,
    pub path: Vec<String>,
    pub promoted: bool,
    pub signals: Vec<String>,
}

#[derive(Debug, Clone, PartialEq, Eq)]
struct NodeState {
    capacity: usize,
    cost: u32,
}

#[derive(Debug, Clone, PartialEq, Eq)]
struct Edge {
    from: String,
    to: String,
    ramp: bool,
}

pub struct OrdoRuntime {
    nodes: HashMap<String, NodeState>,
    edges: Vec<Edge>,
    next_thread_id: u32,
}

impl OrdoRuntime {
    pub fn new() -> Self {
        OrdoRuntime {
            nodes: HashMap::new(),
            edges: Vec::new(),
            next_thread_id: 1,
        }
    }

    pub fn add_node(&mut self, name: &str) {
        self.nodes.insert(name.to_string(), NodeState { capacity: usize::MAX, cost: 0 });
    }

    pub fn connect(&mut self, from: &str, to: &str) {
        self.edges.push(Edge { from: from.to_string(), to: to.to_string(), ramp: false });
    }

    pub fn add_ramp(&mut self, from: &str, to: &str) {
        self.edges.push(Edge { from: from.to_string(), to: to.to_string(), ramp: true });
    }

    pub fn set_capacity(&mut self, node: &str, capacity: usize) {
        if let Some(node_state) = self.nodes.get_mut(node) {
            node_state.capacity = capacity;
        }
    }

    pub fn set_cost(&mut self, node: &str, cost: u32) {
        if let Some(node_state) = self.nodes.get_mut(node) {
            node_state.cost = cost;
        }
    }

    pub fn preload_targets(&self, from: &str) -> Vec<String> {
        self.edges
            .iter()
            .filter(|edge| edge.from == from)
            .map(|edge| edge.to.clone())
            .collect()
    }

    pub fn route_for_budget(&self, candidates: &[&str], budget: u32) -> Option<String> {
        for &candidate in candidates {
            if let Some(node_state) = self.nodes.get(candidate) {
                if node_state.cost <= budget {
                    return Some(candidate.to_string());
                }
            }
        }
        None
    }

    pub fn publish(&mut self, from: &str, topic: &str, payload: &str) -> Trace {
        let thread_id = self.next_thread_id;
        self.next_thread_id += 1;

        let mut path = Vec::new();
        let mut promoted = false;
        let mut signals = Vec::new();

        let mut current = from.to_string();
        path.push(current.clone());

        loop {
            // Check capacity for backpressure
            if let Some(node_state) = self.nodes.get(&current) {
                if node_state.capacity == 0 {
                    signals.push(format!("backpressure:{}", current));
                }
            }

            // Find next edge
            let edge_opt = self.edges.iter().find(|edge| edge.from == current).cloned();
            match edge_opt {
                Some(edge) => {
                    // Mark promotion if crossing a ramp
                    if edge.ramp {
                        promoted = true;
                    }
                    current = edge.to.clone();
                    path.push(current.clone());
                },
                None => break,
            }
        }

        Trace {
            thread_id,
            path,
            promoted,
            signals: if signals.is_empty() { vec!["none".to_string()] } else { signals },
        }
    }
}
