use std::io::Read;
use rust_ordo_ext::{OrdoRuntime, Message};

fn main() {
    let mut input = String::new();
    std::io::stdin().read_to_string(&mut input).unwrap();

    let mut runtime = OrdoRuntime::new();

    for line in input.lines() {
        let parts: Vec<&str> = line.split_whitespace().collect();
        if parts.is_empty() { continue; }

        match parts[0] {
            "node" => {
                if parts.len() < 2 { continue; }
                runtime.add_node(parts[1]);
            },
            "connect" => {
                if parts.len() < 3 { continue; }
                runtime.connect(parts[1], parts[2]);
            },
            "ramp" => {
                if parts.len() < 3 { continue; }
                runtime.add_ramp(parts[1], parts[2]);
            },
            "capacity" => {
                if parts.len() < 3 { continue; }
                let capacity: usize = parts[2].parse().unwrap();
                runtime.set_capacity(parts[1], capacity);
            },
            "cost" => {
                if parts.len() < 3 { continue; }
                let cost: u32 = parts[2].parse().unwrap();
                runtime.set_cost(parts[1], cost);
            },
            "publish" => {
                if parts.len() < 4 { continue; }
                let from = parts[1];
                let topic = parts[2];
                let payload = parts[3..].join(" ");
                let trace = runtime.publish(from, topic, &payload);
                println!(
                    "thread={} path={} promoted={} signals={}",
                    trace.thread_id,
                    trace.path.join(">"),
                    trace.promoted,
                    if trace.signals.len() == 1 && trace.signals[0] == "none" {
                        "none".to_string()
                    } else {
                        trace.signals.join(",")
                    }
                );
            },
            _ => {},
        }
    }
}
